exports.init = (params, rng) => {
  const b_inv = params.invasiveBirthRate ?? 0.6;
  const m_inv = params.invasiveEnemyMortality ?? 0.05;
  const b_nat = params.nativeBirthRate ?? 0.3;
  const m_nat = params.nativeEnemyMortality ?? 0.2;
  const K = params.carryingCapacity ?? 10000;
  const N_inv0 = params.initial_invasive ?? 10;
  const N_nat0 = params.initial_native ?? 1000;
  const alpha = params.competitionAlpha ?? 1;
  const agg = params.invasiveAggressiveness ?? 1;
  return { N_inv: N_inv0, N_nat: N_nat0, K, b_inv, m_inv, b_nat, m_nat, alpha, agg, tick: 0 };
};
exports.step = (state, params, rng) => {
  let { N_inv, N_nat, K, b_inv, m_inv, b_nat, m_nat, alpha, agg, tick } = state;
  if (params) {
    if (typeof params.carryingCapacity !== 'undefined') K = params.carryingCapacity;
    if (typeof params.invasiveBirthRate !== 'undefined') b_inv = params.invasiveBirthRate;
    if (typeof params.invasiveEnemyMortality !== 'undefined') m_inv = params.invasiveEnemyMortality;
    if (typeof params.nativeBirthRate !== 'undefined') b_nat = params.nativeBirthRate;
    if (typeof params.nativeEnemyMortality !== 'undefined') m_nat = params.nativeEnemyMortality;
    if (typeof params.competitionAlpha !== 'undefined') alpha = params.competitionAlpha;
    if (typeof params.invasiveAggressiveness !== 'undefined') agg = params.invasiveAggressiveness;
  }
  const r_inv = b_inv - m_inv;
  const r_nat = b_nat - m_nat;
  const diff_inv = Math.max(0, r_inv - r_nat);
  const diff_nat = Math.max(0, r_nat - r_inv);
  const alpha_eff_nat = alpha * (1 + diff_inv * 2);
  const alpha_eff_inv = alpha * (1 + diff_nat * 2);
  const total_inv_comp = N_inv + alpha_eff_inv * N_nat;
  const total_nat_comp = N_nat + alpha_eff_nat * N_inv;
  let growth_inv = 0;
  let growth_nat = 0;
  if (r_inv > 0) {
    growth_inv = r_inv * N_inv * (1 - total_inv_comp / K);
  } else {
    growth_inv = r_inv * N_inv;
  }
  if (r_nat > 0) {
    growth_nat = r_nat * N_nat * (1 - total_nat_comp / K);
  } else {
    growth_nat = r_nat * N_nat;
  }
  if (N_inv > 0 || N_nat > 0) {
    const sd_inv = Math.sqrt(Math.max(1, Math.abs(growth_inv) + N_inv * 0.05)) * 0.25;
    const sd_nat = Math.sqrt(Math.max(1, Math.abs(growth_nat) + N_nat * 0.05)) * 0.25;
    growth_inv += rng.normal(0, sd_inv);
    growth_nat += rng.normal(0, sd_nat);
  }
  let new_N_inv = N_inv + growth_inv;
  let new_N_nat = N_nat + growth_nat;
  new_N_inv = Math.max(0, Math.round(new_N_inv));
  new_N_nat = Math.max(0, Math.round(new_N_nat));
  const cap = K * 2;
  if (new_N_inv > cap) new_N_inv = cap;
  if (new_N_nat > cap) new_N_nat = cap;
  tick++;
  return { N_inv: new_N_inv, N_nat: new_N_nat, K, b_inv, m_inv, b_nat, m_nat, alpha, agg, tick };
};
exports.observe = (state, params) => {
  const total = state.N_inv + state.N_nat;
  const frac = total > 0 ? state.N_inv / total : 0;
  return { invasive_count: state.N_inv, native_count: state.N_nat, total_population: total, invasive_fraction: frac, invader_look_size: state.agg };
};
exports.view = (state, params) => {
  const total = state.N_inv + state.N_nat;
  const maxAgents = 300;
  let visInv, visNat;
  if (total === 0) { visInv = 0; visNat = 0; } else if (total <= maxAgents) { visInv = state.N_inv; visNat = state.N_nat; } else { visInv = Math.round((state.N_inv / total) * maxAgents); visNat = maxAgents - visInv; }
  const agents = [];
  function pseudoRandom(i) { const x = Math.sin(i * 12.9898 + state.tick * 0.13) * 43758.5453; return x - Math.floor(x); }
  for (let i = 0; i < visInv; i++) { const x = pseudoRandom(i*2); const y = pseudoRandom(i*2+1); agents.push({ id: `inv-${i}`, x, y, tint: 0.25 + (state.agg - 1) / 9 * 0.5, sprite: "invader", bubble: state.agg > 6 ? "!" : undefined }); }
  for (let i = 0; i < visNat; i++) { const x = pseudoRandom(1000 + i*2); const y = pseudoRandom(1000 + i*2+1); agents.push({ id: `nat-${i}`, x, y, tint: 0.65, sprite: "native" }); }
  return { kind: "population", agents };
};
